function coldBath(x,y,label){return path(`M${x-89} ${y-47}V${y+25}Q${x-89} ${y+41} ${x-74} ${y+41}H${x+74}Q${x+89} ${y+41} ${x+89} ${y+25}V${y-47}`,'#e5f2fb','#82b3d0',2)+path(`M${x-89} ${y-17}Q${x-40} ${y-24} ${x} ${y-17}T${x+89} ${y-17}`,'none','#aad0e6',2)+lines(x,y+66,label,28,14);}
